g=demo_in;H=8;W=3
vals={}
for i in range(H):
    if len(set(g[i]))==1: vals.setdefault(g[i][0],[]).append(i)
cands=[(v,r) for v,r in vals.items() if len(r)>=2]
print(cands)
dv,rows=min(cands,key=lambda kv:len(kv[1]))
bounds=[];start=0
for i in range(H):
    if g[i]==[dv]*W: bounds.append((start,i));start=i+1
bounds.append((start,H))
print(dv,bounds)
chunks=[(a,b) for a,b in bounds if b>a]
def score(ab): return sum(1 for r in g[ab[0]:ab[1]] for x in r if x!=dv)
print([(c,score(c)) for c in chunks])
a,b=max(chunks,key=score);print(a,b)
